        d.put("ability timers/color", "Colour of this timer's line on the Ability Timers HUD.");
        d.put("ability timers/enabled", "Turns just this one timer on or off, without deleting it or touching the others.");
        d.put("arrow align/highlight color", "Colour of the box drawn on frames that still need clicking. The alpha slider sets how solid the box is.");
        d.put("arrow align/trigger bot delay", "Cheat build only. How long in milliseconds your crosshair must sit on a frame before Trigger Bot clicks it. Default 67 ms is 15 clicks/second.");
        d.put("croesus / chest profit/highlight runs", "In the Croesus menu, outlines each run green when you have claimed nothing from it yet and reds out the ones you have, before you open them.");
        d.put("croesus / chest profit/second best with key", "Also highlights the second-best chest in a run view, but only when it still profits after paying for a Dungeon Chest Key.");
        d.put("croesus / chest profit/open profit tracker", "Opens the /croesus tracker: session and all-time totals per floor, every item you have ever claimed, and the run numbers of your big drops.");
        d.put("croesus / chest profit/use chest keys", "Cheat build only. Lets Auto Croesus spend a Dungeon Chest Key on a further chest in the same run once the first one is claimed.");
        d.put("croesus / chest profit/chest key min profit", "Cheat build only. A key chest is only opened when its profit, with the key's Bazaar price already subtracted, clears this.");
        d.put("croesus / chest profit/use kismets", "Cheat build only. Lets Auto Croesus spend a Kismet Feather to reroll a poor Bedrock chest. Once per run, and it stops asking for the session if you are not carrying one.");
        d.put("croesus / chest profit/reroll below", "Cheat build only. Bedrock chests worth less than this get rerolled with a Kismet Feather instead of being skipped.");
        d.put("secret sound/sound", "Which sound Secret Sound plays (Experience Orb, Note Pling, Level Up, Anvil Land and more). Click to cycle, then use Play Sound to preview.");
