        d.put("class colors/tab list", "Recolours each teammate's name in the tab list by their dungeon class. Needs Class Colors ON.");
        d.put("class colors/nametags", "Draws a class-coloured tag like [M] Name above each teammate (not you), visible through walls. The normal name tag still shows. Needs Class Colors ON.");
        d.put("secret aura/levers", "Lets Secret Aura flip levers in dungeon rooms (never in Water Board or Tic Tac Toe). Does not affect boss levers.");
        d.put("secret aura/chests", "Lets Secret Aura open secret chests and trapped chests in dungeon rooms.");
        d.put("secret aura/wither essence", "Lets Secret Aura click Wither Essence skulls, using the separate Skull Range.");
        d.put("secret aura/swing hand", "Plays your arm swing each time Secret Aura clicks something. OFF clicks without swinging.");
        d.put("secret aura/pause while sneaking", "Stops Secret Aura while you hold sneak.");
        d.put("secret aura/range", "Maximum distance in blocks this feature reaches.");
        d.put("secret aura/skull range", "How close a Wither Essence skull must be for Secret Aura to click it, in blocks (2.1-4.7).");
        d.put("secret aura/click cooldown", "Secret Aura's minimum time between clicks, in ms; a secret must also stay in range this long before its first click (100-2000).");
        d.put("secret aura/pause while holding", "Type item names or Skyblock IDs separated by commas; Secret Aura pauses while your held item matches any of them (not case-sensitive, partial match).");
        d.put("lever aura/min delay", "Shortest random wait between Lever Aura flicks, in ms (50-2000). Raising it past Max Delay pushes Max Delay up.");
        d.put("lever aura/max delay", "Longest random wait between Lever Aura flicks, in ms (50-2000). Lowering it below Min Delay pulls Min Delay down.");
        d.put("stat bars", "Renamed from Player Stats. Hides the vanilla hearts/hunger/armor/air bars and shows your own Health/Mana/Defense as a HUD line read from the action bar; the real action bar itself is left unchanged.");
        d.put("stat bars/hearts", "Hides the vanilla heart bar. Also hides yellow absorption hearts, since vanilla draws both from the same element.");
        d.put("stat bars/hunger", "Hides the vanilla hunger/food bar. You still stop sprinting below 6 food with no on-screen warning once this is on.");
        d.put("stat bars/armor bar", "Hides the vanilla armor points bar.");
        d.put("stat bars/air bar", "Hides the vanilla air/breath bubbles bar.");
        d.put("stat bars/unhide hearts in rift", "Shows the vanilla heart bar again while inside The Rift, where hearts mean something different than on the main Skyblock islands. Only appears while Hearts is hidden above.");
        d.put("slot binds/show binds", "Whether the border and link line for a bound pair are always drawn, or only while your mouse is over one of the two slots.");
        d.put("slot binds/border color", "Colour of the border and connecting line drawn on bound slots. Scoped separately from Custom Scoreboard's own 'Border Color' key.");
        d.put("wither doors/enabled", "Highlights the nearest locked Wither door. Red by default; turns green once you (or a teammate) picks up a Wither Key. Never shows a door through walls - the legit build only ever highlights the one door you could already see.");
        d.put("wither doors/wither door color", "Color of a locked Wither door you don't have the key for yet.");
        d.put("wither doors/wither door (key) color", "Color the nearest Wither door switches to once a Wither Key has been picked up.");
        d.put("wither doors/render distance", "How far away, in blocks, a door can be and still get highlighted, 32-256.");
        d.put("wither doors/show all doors", "Cheat build only. Also highlights every other locked Wither door and the Blood door, not just the closest Wither door. The closest Wither door (and the Blood door, once you have its key) still use their own key-held color so they stand out from the rest.");
        d.put("wither doors/blood door color", "Cheat build only. Color of the locked Blood door while you don't have the Blood Key.");
        d.put("wither doors/blood door (key) color", "Cheat build only. Color the Blood door switches to once the Blood Key has been picked up.");
        d.put("wither doors/through walls", "Cheat build only. Draws the highlighted door box(es) through walls instead of only when you can actually see them.");
        d.put("mask invincibility/item icons", "Draws each item's real texture next to its timer, taken from your own inventory when it is there.");
        d.put("mask invincibility/hide mask names", "Shows only the icon and the time, dropping the \"Spirit Mask:\" label. Needs Item Icons on.");
        d.put("mask invincibility/announce in chat", "Prints a client-side line only you can see when a mask or the Phoenix pet pops.");
        d.put("mask invincibility/announce to party", "Types the pop into party chat with /pc so your team sees it. Off by default - this really does send a message.");
        d.put("mask invincibility/swap step delay", "Pause between each step of an automated swap: send /stats, wait for the menu, click the mask, close it. Higher is safer on a laggy server.");
        d.put("mask invincibility/phoenix rod", "Part of the name of the rod to throw for Phoenix, matched anywhere in a hotbar item's name. Relies on your own Hypixel Autopet rule that summons Phoenix when you hold it.");
        d.put("mask invincibility/return to slot", "Switches back to whatever you were holding once the rod has been thrown.");
        d.put("mask invincibility/phoenix route", "How an automated swap puts Phoenix out: Rod / Autopet throws your rod and relies on a Hypixel Autopet rule to summon it (no command sent), /pets menu opens /pets and clicks Phoenix directly. Falls back to /pets on its own if no rod is found in your hotbar.");
        d.put("phoenix rod", "Part of the name of the rod to throw for Phoenix, matched anywhere in a hotbar item's name. Only used by the Rod / Autopet route - relies on your own Hypixel Autopet rule that summons Phoenix when you hold it. If no matching rod is found, the swap falls back to the /pets menu instead of doing nothing.");
        d.put("storage search/storage search", "Searches every storage, chest and menu this mod has cached, not just the container that's open. Opens with /search, its own binds, or the Search button in the Storage Overlay.");
        d.put("storage search/open bind 1", "Click, then press the key or mouse button that opens the search. Hold Ctrl/Shift/Alt first for a combination like Ctrl+F. Escape cancels.");
        d.put("storage search/open bind 2", "A second way to open the search. Click, then press a key or mouse button; hold Ctrl/Shift/Alt first for a combination.");
